        this.addAnnotation((ENamedElement)this.canTpAddressEClass.getEOperations().get(1), source, new String[]{"body", "tpAddressExtensionValue.setRadix(newTpAddressExtensionValue.getRadix());\ntpAddressExtensionValue.setNoOfDigits(newTpAddressExtensionValue.getNoOfDigits());\nsetTpAddressExtensionValue(newTpAddressExtensionValue.getValue());\n"});
