        this.addAnnotation((ENamedElement)this.getCanTpAddress_TpAddress(), source, new String[]{"documentation", "An ECUs TP address on the referenced channel. This represents the diagnostic Address. "});
        this.addAnnotation((ENamedElement)this.getCanTpAddress_TpAddressExtensionValue(), source, new String[]{"documentation", "If the mixed addressing format is used, this parameter contains the transport protocol address extension value."});
