        this.addAnnotation((ENamedElement)this.canTpAddressingFormatTypeEEnum.getELiterals().get(2), source, new String[]{"documentation", "To use extended addressing format."});
        this.addAnnotation((ENamedElement)this.canTpChannelEClass, source, new String[]{"documentation", "Configuration parameters of the CanTp channel."});
        this.addAnnotation((ENamedElement)this.canTpChannelEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.PositiveIntegerDatatype%>)channelId.clone();"});
        this.addAnnotation((ENamedElement)this.canTpChannelEClass.getEOperations().get(1), source, new String[]{"body", "channelId.setRadix(newChannelId.getRadix());\nchannelId.setNoOfDigits(newChannelId.getNoOfDigits());\nsetChannelId(newChannelId.getValue());\n"});
        this.addAnnotation((ENamedElement)this.getCanTpChannel_ChannelId(), source, new String[]{"documentation", "The id of the channel. The value shall be unique for each channel.\r\n"});
        this.addAnnotation((ENamedElement)this.getCanTpChannel_ChannelMode(), source, new String[]{"documentation", "The CAN Transport Layer supports half and full duplex channel modes."});
        this.addAnnotation((ENamedElement)this.getCanTpChannel_VariationPoint(), source, new String[]{"documentation", "This element was generated/modified due to an atpVariation stereotype."});
        this.addAnnotation((ENamedElement)this.canTpChannelModeTypeEEnum, source, new String[]{"documentation", "The CAN Transport Layer supports half and full duplex channel modes."});
        this.addAnnotation((ENamedElement)this.canTpChannelModeTypeEEnum.getELiterals().get(0), source, new String[]{"documentation", "full duplex channel mode"});
